package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string          // PIC X(2) @0 len=2
	BrAcct   string          // PIC X(4) @2 len=4
	BrType   string          // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"    // PIC X len=1 = "N"
var WsFirstFlag string = "Y"  // PIC X len=1 = "Y"
var WsPrevBranch string = "  " // PIC X(2) len=2 = SPACES
var WsPrevAcct string = "    " // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal = decimal.NewFromInt(0)       // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0) // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)  // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 = 0                                 // PIC 99 len=2 = 0
var WsAmtEd string                                       // PIC ZZ,ZZ9.99 len=9
var WsBalEd string                                       // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string                                       // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var ledgerFile *os.File
var ledgerReader *bufio.Reader
var ledgerRec LedgerRec

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatEdited(picture string, val decimal.Decimal) string {
	// determine sign handling
	hasSign := strings.HasPrefix(picture, "-") || strings.HasPrefix(picture, "+")
	signChar := ""
	bodyPic := picture
	if hasSign {
		bodyPic = picture[1:]
		if val.IsNegative() {
			signChar = "-"
		} else {
			signChar = " "
		}
		if strings.HasPrefix(picture, "+") {
			if val.IsNegative() {
				signChar = "-"
			} else {
				signChar = "+"
			}
		}
	}

	// count integer and fractional digit slots
	dotIdx := strings.Index(bodyPic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = bodyPic[:dotIdx]
		fracPic = bodyPic[dotIdx+1:]
	} else {
		intPic = bodyPic
		fracPic = ""
	}
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracSlots++
		}
	}

	absVal := val.Abs()
	// Ensure correct scale by truncating/rounding? Use string formatting with scale
	// For MOVE to edited, we will round to fracSlots (half away if needed) ?
	// For this program amounts exact, use Round.
	absVal = absVal.Round(int32(fracSlots))

	// Extract integer and fractional strings
	// Use Shift to avoid float
	// Get integer part and fractional part
	intPart := absVal.Truncate(0)
	// fractional part
	fracPartStr := ""
	if fracSlots > 0 {
		// get fractional digits
		// frac = (absVal - intPart) * 10^fracSlots
		pow := decimal.NewFromInt(1)
		for i := 0; i < fracSlots; i++ {
			pow = pow.Mul(decimal.NewFromInt(10))
		}
		fracVal := absVal.Sub(intPart).Mul(pow).Round(0).Abs()
		// format with leading zeros
		s := fracVal.StringFixed(0) // integer string
		// pad
		if len(s) < fracSlots {
			s = strings.Repeat("0", fracSlots-len(s)) + s
		} else if len(s) > fracSlots {
			s = s[len(s)-fracSlots:]
		}
		fracPartStr = s
	}

	intStr := intPart.StringFixed(0)
	if intStr[0] == '-' {
		intStr = intStr[1:]
	}
	// handle overflow: keep low-order digits
	if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}
	// pad left with zeros to intSlots
	if len(intStr) < intSlots {
		intStr = strings.Repeat("0", intSlots-len(intStr)) + intStr
	}
	// intStr now length intSlots, each char corresponds to a digit slot in order

	// Build body result array
	bodyLen := len(bodyPic)
	res := make([]byte, bodyLen)
	// Fill fractional part from left to right (fracPic chars are all 9)
	fracDigitIdx := 0
	for i := bodyLen - 1; i >= 0; i-- {
		// identify if this position is after dot
		if dotIdx >= 0 && i > dotIdx-0 { // careful: dot position in bodyPic
			// bodyPic index equals res index
		}
	}
	// Simpler: walk bodyPic index
	digitIdx := intSlots - 1 // index into intStr
	// We need to place integer digits into Z/9 positions from rightmost to left
	// Create slice for integer digit char at each bodyPic position (or 0 if not digit)
	intDigitAtPos := make([]byte, bodyLen)
	for i := range intDigitAtPos {
		intDigitAtPos[i] = 0
	}
	// assign digits to Z/9 positions in intPic region
	for i := len(intPic) - 1; i >= 0; i-- {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			intDigitAtPos[i] = intStr[digitIdx]
			digitIdx--
		}
	}
	// Determine suppression: find first non-zero digit position (most significant)
	firstNonZeroPos := -1
	for i := 0; i < len(intPic); i++ {
		if intDigitAtPos[i] != 0 && intDigitAtPos[i] != '0' {
			firstNonZeroPos = i
			break
		}
	}
	// Build result for int part + dot + frac
	for i := 0; i < bodyLen; i++ {
		pc := bodyPic[i]
		switch pc {
		case 'Z', '9':
			d := intDigitAtPos[i]
			if pc == 'Z' && firstNonZeroPos != -1 && i < firstNonZeroPos {
				// actually if i is before first non-zero, it's suppressed
				// but if all zeros, firstNonZeroPos == -1, suppress all Z
				res[i] = ' '
			} else if pc == 'Z' && firstNonZeroPos == -1 {
				// check if this is the last digit position (rightmost) that must show zero
				// For Z,ZZ9 pattern, the '9' is not Z, so this case only for Z positions when value is zero
				// They should be spaces, leaving the '9' to show 0
				res[i] = ' '
			} else {
				// need to check if pc is Z and digit is 0 and i < firstNonZeroPos
				if pc == 'Z' && firstNonZeroPos != -1 && i < firstNonZeroPos && d == '0' {
					res[i] = ' '
				} else if pc == 'Z' && firstNonZeroPos == -1 {
					res[i] = ' '
				} else {
					res[i] = d
				}
			}
		case ',':
			// comma is suppressed if still in leading zero suppression area
			if firstNonZeroPos == -1 {
				res[i] = ' '
			} else if i < firstNonZeroPos {
				res[i] = ' '
			} else {
				res[i] = ','
			}
		case '.':
			res[i] = '.'
		default:
			res[i] = byte(pc)
		}
	}
	// Now fill fractional digits: fractional positions are after dot, each '9' gets a digit
	for i := dotIdx + 1; i < bodyLen && fracDigitIdx < len(fracPartStr); i++ {
		if bodyPic[i] == '9' || bodyPic[i] == 'Z' {
			res[i] = fracPartStr[fracDigitIdx]
			fracDigitIdx++
		}
	}

	bodyStr := string(res)
	if hasSign {
		return signChar + bodyStr
	}
	return bodyStr
}

func formatWsAmtEd(v decimal.Decimal) string {
	return formatEdited("ZZ,ZZ9.99", v)
}
func formatWsBalEd(v decimal.Decimal) string {
	return formatEdited("-Z,ZZZ,ZZ9.99", v)
}
func formatWsTotEd(v decimal.Decimal) string {
	return formatEdited("-ZZZ,ZZZ,ZZ9.99", v)
}
func formatWsSkipped(v int64) string {
	s := fmt.Sprintf("%d", v)
	if len(s) < 2 {
		s = strings.Repeat("0", 2-len(s)) + s
	} else if len(s) > 2 {
		s = s[len(s)-2:]
	}
	return s
}

// Paragraph functions

func MainPara() {
	OpenLedger()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	ledgerFile.Close()
	GrandPara()
}

func ReadPara() {
	line, err := ledgerReader.ReadString('\n')
	if err != nil {
		// EOF if no data
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
		// last line without newline still processed
	}
	// Trim line endings but keep spaces
	line = strings.TrimRight(line, "\r\n")
	if err != nil && len(line) == 0 {
		WsEofFlag = "Y"
		return
	}
	if err != nil {
		// io.EOF with data: process it, next read will be EOF
		// we will set flag next call; for now continue
		// To simulate COBOL, we need to handle correctly: this read succeeded
		// So don't set EOF yet if we have data
		// The above condition len==0 handles true EOF
	}
	// If line shorter than 14, pad
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	}
	if len(line) > 14 {
		line = line[:14]
	}
	// Parse
	ledgerRec.BrBranch = line[0:2]
	ledgerRec.BrAcct = line[2:6]
	ledgerRec.BrType = line[6:7]
	amtStr := line[7:14] // 7 digits
	amtStr = strings.TrimSpace(amtStr)
	if amtStr == "" {
		amtStr = "0"
	}
	// amtStr should be digits, interpret as integer then shift -2
	// Also may contain spaces? Already trimmed
	d, err := decimal.NewFromString(amtStr)
	if err != nil {
		// if spaces or non-numeric, treat as 0
		d = decimal.NewFromInt(0)
	}
	// IMPLIED decimal V99: shift -2
	d = decimal.New(d.IntPart(), -2)
	ledgerRec.BrAmt = d

	// If we had EOF on next read, the next ReadPara call will detect
	// For the case where ReadString returned EOF with data, we need to remember
	// that next call should be EOF. We achieve by peeking: if err != nil and we processed data,
	// we set a pending EOF flag to be consumed on next call
	// Simpler: if err != nil (EOF) we will not set EOF now, but next read will get empty
	if err != nil {
		// check if underlying file at EOF: next read will set EOF
		// We use a wrapper: set a flag to indicate next read is EOF
		// Implement by checking if ledgerReader buffered remaining ==0
		// Instead, we can peek: if we are at EOF, next ReadString will return 0,eof
		// So do nothing; next call will set EOF
		// But we need to avoid losing the current record: we already processed it
		// Keep EOF flag N for now
		// To ensure next call returns EOF, we can check if err == io.EOF -> set a marker
		// Use a global pendingEOF
		pendingEOF = true
	}
}

var pendingEOF bool

func ReadParaWrapper() {
	if pendingEOF {
		// The previous read was last line; now truly EOF
		// But we have already processed that line; need to signal EOF on next invocation
		// This function is called separately, so we should check pending
		// Actually we set pending after processing a line that had EOF; the next call should set EOF without reading
		pendingEOF = false
		// Peek if there's more data? If file truly ended, set EOF
		// Try to read one more byte
		_, err := ledgerReader.Peek(1)
		if err != nil {
			WsEofFlag = "Y"
			return
		}
	}
	ReadPara()
	// If ReadPara read the last line and hit EOF, pendingEOF will be true, but we don't set WsEofFlag yet
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevBranch = ledgerRec.BrBranch
		WsPrevAcct = ledgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if ledgerRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = ledgerRec.BrBranch
			WsPrevAcct = ledgerRec.BrAcct
		} else {
			if ledgerRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = ledgerRec.BrAcct
			}
		}
	}
	PostPara()
	ReadParaWrapper()
}

func PostPara() {
	WsAmtEd = formatWsAmtEd(ledgerRec.BrAmt)
	switch ledgerRec.BrType {
	case "D":
		WsBal = WsBal.Add(ledgerRec.BrAmt)
		fmt.Fprintln(os.Stdout, ledgerRec.BrAcct+" D "+WsAmtEd)
	case "C":
		WsBal = WsBal.Sub(ledgerRec.BrAmt)
		fmt.Fprintln(os.Stdout, ledgerRec.BrAcct+" C "+WsAmtEd)
	default:
		WsSkipped++
		fmt.Fprintln(os.Stdout, ledgerRec.BrAcct+" ? SKIPPED")
	}
}

func AcctBreakPara() {
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Fprintln(os.Stdout, "  ACCOUNT "+WsPrevAcct+" BALANCE:"+WsBalEd)
	WsBranchTot = WsBranchTot.Add(WsBal)
	WsBal = decimal.NewFromInt(0)
}

func BranchBreakPara() {
	WsTotEd = formatWsTotEd(WsBranchTot)
	fmt.Fprintln(os.Stdout, " BRANCH "+WsPrevBranch+" TOTAL:"+WsTotEd)
	WsGrandTot = WsGrandTot.Add(WsBranchTot)
	WsBranchTot = decimal.NewFromInt(0)
}

func GrandPara() {
	WsTotEd = formatWsTotEd(WsGrandTot)
	fmt.Fprintln(os.Stdout, "GRAND TOTAL:"+WsTotEd)
	fmt.Fprintln(os.Stdout, "SKIPPED: "+formatWsSkipped(WsSkipped))
}

func OpenLedger() {
	var err error
	ledgerFile, err = os.Open("input.dat")
	if err != nil {
		// create empty
		ledgerFile, _ = os.Open("input.dat")
		WsEofFlag = "Y"
		ledgerReader = bufio.NewReader(ledgerFile)
		return
	}
	ledgerReader = bufio.NewReader(ledgerFile)
}

func main() {
	OpenLedger()
	// initial read
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	if ledgerFile != nil {
		ledgerFile.Close()
	}
	GrandPara()
}
